	@ParameterizedTest
	@EnumSource(Terminal.class)
	void emptyAttemptRetiresNormallyAndRejectsLateBorrow(Terminal terminal) {
		NativeFilterLease attempt = new NativeFilterLease();
		RuntimeException primary = new IllegalStateException("empty attempt stopped");
		attempt.selected();
		switch (terminal) {
		case COMMIT -> attempt.commit();
		case DISCARD -> attempt.discard();
		case ABORT -> attempt.abort(primary);
		}
		attempt.discard();
		attempt.commit();
		attempt.abort(primary);
		assertEquals(0, primary.getSuppressed().length);
		assertThrows(IllegalStateException.class, () -> attempt.borrow(new IdentityOnlyFilter()));
	}

