	@Test
	void sharedSelectedMemoGraphRetainsOneUnqualifiedDiagnosticCensus() {
		NativeExecutionContext owner = new NativeExecutionContext();
		Diagnostics statistics = new Diagnostics();
		RecordingNativeBooleanFilter template = recording(statistics);
		NativeFilterLease producer = NativeFilterLease.capture(owner);
		producer.openUnqualified(template, owner).terminal(2L, 1L, true);
		NativeFilterLease.Frozen leaf = producer.freeze(true);
		NativeFilterLease parentProducer = NativeFilterLease.capture(owner);
		parentProducer.include(leaf, owner);
		parentProducer.include(leaf, owner);
		NativeFilterLease.Frozen parent = parentProducer.freeze(true);
		NativeFilterLease selected = new NativeFilterLease();
		selected.include(parent, owner);
		selected.include(leaf, owner);
		selected.commit();
		owner.close();
		assertEquals(1, statistics.observations.size());
		var observation = statistics.observations.getFirst();
		assertEquals(2L, observation.passedCount());
		assertEquals(1L, observation.filteredCount());
		assertFalse(observation.completed(), "component diagnostics cannot mint complete LMDB feedback authority");
	}

