	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void pendingWaitersShareTheirCloseFailureAndLateProducerCleansItsOwnState(boolean cleanupFails) throws Exception {
		NativeExecutionContext owner = new NativeExecutionContext();
		Object key = new Object();
		CountDownLatch entered = new CountDownLatch(1), release = new CountDownLatch(1);
		AtomicInteger closes = new AtomicInteger();
		AtomicReference<Thread> firstThread = new AtomicReference<>(), secondThread = new AtomicReference<>();
		RuntimeException cleanup = new IllegalStateException("late producer cleanup");
		try (var workers = Executors.newFixedThreadPool(3)) {
			try {
				var producer = workers.submit(() -> outcome(() -> owner.nativeState(key, () -> {
					entered.countDown();
					awaitLatch(release);
					return (AutoCloseable) () -> {
						closes.incrementAndGet();
						if (cleanupFails)
							throw cleanup;
					};
				})));
				assertTrue(entered.await(5, TimeUnit.SECONDS));
				var first = workers.submit(() -> {
					firstThread.set(Thread.currentThread());
					return outcome(() -> owner.nativeState(key, () -> {
						throw new AssertionError("duplicate factory");
					}));
				});
				var second = workers.submit(() -> {
					secondThread.set(Thread.currentThread());
					return outcome(() -> owner.nativeState(key, () -> {
						throw new AssertionError("duplicate factory");
					}));
				});
				awaitWaiter(firstThread);
				awaitWaiter(secondThread);
				owner.close();
				assertTrue(owner.isClosed());
				Throwable firstFailure = first.get(5, TimeUnit.SECONDS),
						secondFailure = second.get(5, TimeUnit.SECONDS);
				assertSame(firstFailure, secondFailure,
						"one actual terminal notification is shared by existing waiters");
				assertEquals(IllegalStateException.class, firstFailure.getClass());
				assertEquals("execution context is closed", firstFailure.getMessage());
				assertEquals(0, firstFailure.getSuppressed().length);
				assertEquals(0, closes.get());
				release.countDown();
				Throwable producerFailure = producer.get(5, TimeUnit.SECONDS);
				assertEquals(IllegalStateException.class, producerFailure.getClass());
				assertEquals("execution context is closed", producerFailure.getMessage());
				assertEquals(cleanupFails ? List.of(cleanup) : List.of(), List.of(producerFailure.getSuppressed()));
				assertEquals(0, firstFailure.getSuppressed().length,
						"late producer cleanup is not another waiter's failure");
				assertEquals(1, closes.get());
			} finally {
				release.countDown();
				owner.close();
			}
		}
	}

	@Test
	void reentrantStateCloseKeepsThePrimaryAndLaterFilterCleanupIdentity() {
		NativeExecutionContext owner = new NativeExecutionContext();
		Error primary = new AssertionError("owned state close");
		RuntimeException later = new IllegalStateException("owned filter close");
		AtomicInteger stateCloses = new AtomicInteger(), filterCloses = new AtomicInteger();
		owner.nativeState(new Object(), () -> (AutoCloseable) () -> {
			stateCloses.incrementAndGet();
			owner.close();
			throw primary;
		});
		owner.ownFilterResource(new NativeBooleanFilter() {
			@Override
			public boolean accept(RowState row) {
				return true;
			}

			@Override
			public void close() {
				filterCloses.incrementAndGet();
				throw later;
			}
		});
		assertSame(primary, assertThrows(Error.class, owner::close));
		assertEquals(List.of(later), List.of(primary.getSuppressed()));
		assertEquals(1, stateCloses.get());
		assertEquals(1, filterCloses.get());
		owner.close();
		assertEquals(1, stateCloses.get());
		assertEquals(1, filterCloses.get());
	}

	private static RecordingNativeBooleanFilter recording(Diagnostics statistics) {
		return new RecordingNativeBooleanFilter(ignored -> true,
				new Filter(new SingletonSet(), new ValueConstant(SimpleValueFactory.getInstance().createLiteral(true))),
				statistics);
	}

	private static Throwable outcome(Runnable action) {
		try {
			action.run();
			return null;
		} catch (Throwable failure) {
			return failure;
		}
	}

	private static void awaitLatch(CountDownLatch latch) {
		try {
			assertTrue(latch.await(5, TimeUnit.SECONDS));
		} catch (InterruptedException failure) {
			Thread.currentThread().interrupt();
			throw new AssertionError(failure);
		}
	}

	private static void awaitWaiter(AtomicReference<Thread> reference) {
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
		while (System.nanoTime() < deadline) {
			Thread thread = reference.get();
			var info = thread == null ? null : ManagementFactory.getThreadMXBean().getThreadInfo(thread.threadId(), 64);
			if (info != null) {
				for (var frame : info.getStackTrace()) {
					if (frame.getClassName().equals(NativeExecutionContext.class.getName())
							&& frame.getMethodName().equals("awaitNativeState"))
						return;
				}
			}
			Thread.onSpinWait();
		}
		throw new AssertionError("existing native-state waiter did not enter the owning future");
	}

	private static final class Diagnostics extends EvaluationStatistics {
		final List<FilterOutcomeObservation> observations = new ArrayList<>();

		@Override
		public void recordFilterOutcome(Filter filter, FilterOutcomeObservation observation) {
			observations.add(observation);
		}
	}

	private static final class IdentityOnlyFilter implements NativeBooleanFilter {
		final AtomicInteger closes = new AtomicInteger();

		@Override
		public boolean accept(RowState row) {
			return true;
		}

		@Override
		public void close() {
			closes.incrementAndGet();
		}

		@Override
		public boolean equals(Object other) {
			throw new AssertionError("filter equality must not grant ownership");
		}

		@Override
		public int hashCode() {
			throw new AssertionError("filter hash must not grant ownership");
		}
	}
